import type {
  InternalTreeMapClusterNode,
  InternalTreeMapDataEntryMeta,
  InternalTreeMapLeafNode,
} from '../types/internal.js';

export const getMetadata = (clusterNodes: InternalTreeMapClusterNode[]) => {
  const metadataMap = new WeakMap<
    InternalTreeMapLeafNode,
    InternalTreeMapDataEntryMeta
  >();
  const metadataSeries: InternalTreeMapLeafNode[] = [];

  clusterNodes.forEach((node) => {
    node.children?.forEach((leaf) => {
      metadataMap.set(leaf, {
        id: `${node.name}-${leaf.name}-${leaf.value}`,
        ...leaf,
      });
      metadataSeries.push(leaf);
    });
  });
  return { metadataSeries, metadataMap };
};
